// Package bicep executes the subscription-scoped infrastructure generated by azure.resources.
package bicep

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"maps"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"slices"
	"strings"
	"sync"

	"github.com/Azure/azure-sdk-for-go/sdk/azcore"
	"github.com/Azure/azure-sdk-for-go/sdk/resourcemanager/resources/armresources"
	"github.com/azure/azure-dev/cli/azd/pkg/azdext"
	"github.com/azure/azure-dev/cli/azd/pkg/grpcbroker"
	"google.golang.org/protobuf/proto"
)

const ownerTag = "azd-resources-owner"

// ParameterResolver supplies optional deployment parameter values and whether they required a local prompt,
// recording their environment mappings. A nil value with no error requests normal Bicep parameter resolution.
// Calls are serialized by the provider; the resolver may update environment values after persisting them.
type ParameterResolver interface {
	ResolveParameter(ctx context.Context, name string, values map[string]string, mapping *[]string) (any, bool, error)
}

// Provider executes generated Bicep without depending on the core provisioning implementation.
// Its lock serializes lifecycle calls and protects the resolved scope, compiled templates, and prepared parameters.
type Provider struct {
	mu          sync.Mutex
	client      *azdext.AzdClient
	options     *azdext.ProvisioningOptions
	path        string
	module      string
	envName     string
	projectName string
	scope       *scope
	name        string
	template    map[string]any
	params      map[string]any
	metadata    []*azdext.ProvisioningParameter
	resolver    ParameterResolver
	azure       backend
	compile     func(context.Context, string) ([]byte, error)
}

var _ azdext.ProvisioningProvider = (*Provider)(nil)

// New creates an execution provider. The caller retains ownership of client.
// A nil resolver uses only normal Bicep parameter resolution.
func New(client *azdext.AzdClient, resolver ParameterResolver) *Provider {
	return &Provider{client: client, resolver: resolver, compile: compileBicep}
}

// Initialize accepts the generated infrastructure directory, not the original project infrastructure path.
func (p *Provider) Initialize(_ context.Context, projectPath string, options *azdext.ProvisioningOptions) error {
	p.mu.Lock()
	defer p.mu.Unlock()

	if options == nil || options.Path == "" {
		return errors.New("generated infrastructure path is required")
	}
	if len(options.DeploymentStacks) != 0 {
		return errors.New("azure.resources does not support deploymentStacks")
	}
	module := options.Module
	if module == "" {
		module = "main"
	}
	if module == "." || module == ".." || strings.ContainsAny(module, `/\`) {
		return errors.New("Bicep module must be a file name without path separators")
	}
	path := options.Path
	if !filepath.IsAbs(path) {
		path = filepath.Join(projectPath, path)
	}
	absolute, err := filepath.Abs(path)
	if err != nil {
		return fmt.Errorf("resolving generated infrastructure path: %w", err)
	}
	p.options = proto.Clone(options).(*azdext.ProvisioningOptions)
	p.path, p.module = absolute, module
	p.template, p.params, p.metadata, p.scope, p.azure = nil, nil, nil, nil, nil
	return nil
}

// Close releases cached secrets; it does not close the shared SDK connection.
func (p *Provider) Close() error {
	p.mu.Lock()
	defer p.mu.Unlock()

	p.template, p.params, p.metadata, p.scope, p.azure = nil, nil, nil, nil, nil
	p.options = nil
	return nil
}

func deploymentName(project, environment, layer string) string {
	// Hash the complete names rather than truncating user names, which could alias two layers.
	identity := fmt.Sprintf("%d:%s%d:%s%s", len(project), project, len(environment), environment, layer)
	return fmt.Sprintf("azd-resources-%x", sha256.Sum256([]byte(identity)))[:61]
}

func (p *Provider) build(ctx context.Context) error {
	if p.template != nil {
		return nil
	}
	if p.options == nil {
		return errors.New("azure.resources provider is not initialized")
	}
	data, err := p.compile(ctx, filepath.Join(p.path, p.module+".bicep"))
	if err != nil {
		return err
	}
	var template map[string]any
	if err := json.Unmarshal(data, &template); err != nil {
		return fmt.Errorf("decoding compiled Bicep: %w", err)
	}
	schema, _ := template["$schema"].(string)
	if !strings.Contains(schema, "subscriptionDeploymentTemplate.json") {
		return errors.New("azure.resources requires a subscription-scoped generated template")
	}
	p.template = template
	return nil
}

func compileBicep(ctx context.Context, path string) ([]byte, error) {
	binary := os.Getenv("AZD_BICEP_TOOL_PATH")
	if binary == "" {
		configDir := os.Getenv("AZD_CONFIG_DIR")
		if configDir == "" {
			home, err := os.UserHomeDir()
			if err != nil {
				return nil, fmt.Errorf("finding azd Bicep installation: %w", err)
			}
			configDir = filepath.Join(home, ".azd")
		}
		name := "bicep"
		// azd stores a native executable, including the Windows suffix, in its config bin directory.
		if runtime.GOOS == "windows" {
			name += ".exe"
		}
		candidate := filepath.Join(configDir, "bin", name)
		// The operator's azd config selects trusted local tooling, not a project-supplied path.
		//nolint:gosec // G703: AZD_CONFIG_DIR is the user's tool installation directory.
		if info, err := os.Stat(candidate); err == nil && !info.IsDir() {
			binary = candidate
		} else {
			binary, _ = exec.LookPath("bicep")
		}
	}
	if binary == "" {
		return nil, &azdext.ToolError{
			ToolName: "bicep", Kind: azdext.ToolErrorKindMissing, Message: "Bicep CLI was not found",
			Suggestion: "Install Bicep on PATH or configure AZD_BICEP_TOOL_PATH.",
		}
	}
	//nolint:gosec // G204: executable comes from operator configuration or PATH; arguments bypass the shell.
	cmd := exec.CommandContext(ctx, binary, "build", path, "--stdout")
	var stderr strings.Builder
	cmd.Stderr = &stderr
	data, err := cmd.Output()
	if err != nil {
		if ctx.Err() != nil {
			return nil, ctx.Err()
		}
		kind := azdext.ToolErrorKindFailed
		// Windows reports a missing path without a file extension as ErrNotFound after trying PATHEXT suffixes.
		if errors.Is(err, os.ErrNotExist) || errors.Is(err, exec.ErrNotFound) {
			kind = azdext.ToolErrorKindMissing
		}
		return nil, &azdext.ToolError{
			ToolName: "bicep", Kind: kind, Err: err,
			Message: "Bicep compilation failed: " + stderr.String(),
		}
	}
	return data, nil
}

// PlannedOutputs enumerates every compiled output without contacting Azure.
func (p *Provider) PlannedOutputs(ctx context.Context) ([]*azdext.ProvisioningPlannedOutput, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if err := p.build(ctx); err != nil {
		return nil, err
	}
	outputs, _ := p.template["outputs"].(map[string]any)
	result := make([]*azdext.ProvisioningPlannedOutput, 0, len(outputs))
	for _, name := range slices.Sorted(maps.Keys(outputs)) {
		result = append(result, &azdext.ProvisioningPlannedOutput{Name: name})
	}
	return result, nil
}

// State returns this project's environment/entry deployment, or the hinted deployment when it is tagged for them.
func (p *Provider) State(
	ctx context.Context, options *azdext.ProvisioningStateOptions,
) (*azdext.ProvisioningStateResult, error) {
	p.mu.Lock()
	defer p.mu.Unlock()
	if err := p.ensureEnv(ctx); err != nil {
		return nil, err
	}
	deployment, err := p.loadDeployment(ctx, options.GetHint())
	if isNotFound(err) {
		return &azdext.ProvisioningStateResult{State: &azdext.ProvisioningState{}}, nil
	}
	if err != nil {
		return nil, fmt.Errorf("reading deployment state: %w", err)
	}
	return deploymentState(deployment)
}

func deploymentTagsMatch(tags map[string]*string, project, environment, layer string) bool {
	return pointerValue(tags["azd-project-name"]) == project &&
		pointerValue(tags["azd-env-name"]) == environment &&
		pointerValue(tags["azd-layer-name"]) == layer
}

func (p *Provider) loadDeployment(ctx context.Context, hint string) (armresources.DeploymentExtended, error) {
	name := p.name
	if hint != "" {
		name = hint
	}
	deployment, err := p.azure.get(ctx, name)
	if err != nil {
		return armresources.DeploymentExtended{}, err
	}
	// A hint can name any subscription deployment, so don't hand back another project's state.
	if name != p.name && !deploymentTagsMatch(deployment.Tags, p.projectName, p.envName, p.options.Name) {
		return armresources.DeploymentExtended{},
			errors.New("deployment does not belong to this project, environment, and entry")
	}
	return deployment, nil
}

func (p *Provider) ownsGroup(group armresources.ResourceGroup) bool {
	return pointerValue(group.Tags[ownerTag]) == p.name
}

func deploymentState(deployment armresources.DeploymentExtended) (*azdext.ProvisioningStateResult, error) {
	state := &azdext.ProvisioningState{Outputs: map[string]*azdext.ProvisioningOutputParameter{}}
	if deployment.Properties == nil {
		return nil, errors.New("Azure deployment response has no properties")
	}
	data, err := json.Marshal(deployment.Properties.Outputs)
	if err != nil {
		return nil, fmt.Errorf("encoding deployment outputs: %w", err)
	}
	var outputs map[string]struct {
		Type  string `json:"type"`
		Value any    `json:"value"`
	}
	if err := json.Unmarshal(data, &outputs); err != nil {
		return nil, fmt.Errorf("decoding deployment outputs: %w", err)
	}
	resourceIDs := map[string]bool{}
	for name, output := range outputs {
		value, err := provisioningValue(output.Value)
		if err != nil {
			return nil, fmt.Errorf("encoding output %s: %w", name, err)
		}
		state.Outputs[name] = &azdext.ProvisioningOutputParameter{Type: output.Type, Value: value}
		if id, ok := output.Value.(string); ok && strings.HasPrefix(strings.ToLower(id), "/subscriptions/") &&
			(strings.HasPrefix(name, "AZURE_RESOURCE_") ||
				strings.HasPrefix(name, "AZURE_RESOURCES_") && strings.Contains(name, "__RESOURCE_")) &&
			strings.HasSuffix(name, "_ID") {
			resourceIDs[id] = true
		}
	}
	for _, resource := range deployment.Properties.OutputResources {
		if resource != nil && resource.ID != nil {
			resourceIDs[*resource.ID] = true
		}
	}
	for _, id := range slices.Sorted(maps.Keys(resourceIDs)) {
		state.Resources = append(state.Resources, &azdext.ProvisioningResource{Id: id})
	}
	return &azdext.ProvisioningStateResult{State: state}, nil
}

func provisioningValue(value any) (string, error) {
	// Stable provisioning carries strings directly, not JSON-quoted strings.
	if text, ok := value.(string); ok {
		return text, nil
	}
	data, err := json.Marshal(value)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func isNotFound(err error) bool {
	response, ok := errors.AsType[*azcore.ResponseError](err)
	return ok && response.StatusCode == 404
}

func report(progress grpcbroker.ProgressFunc, message string) {
	if progress != nil {
		progress(message)
	}
}
